(()=>{"use strict";const P="";
const K="hgisbt";
const S={n:"R2VyYWRvciBkZSBDYXJpbWJv",s:"U29sdGUgdW0gZGVzZW5obywgYWp1c3RlIGUgYmFpeGUgbyBTVEwuIE5hZGEgYXF1aSBmaWNhIHNhbHZvIG5vIG5hdmVnYWRvci4=",m:"w4FyZWEgcmVzdHJpdGE=",p:"Q8OzZGlnbyBkZSBhY2Vzc28=",e:"Q8OzZGlnbyBpbmNvcnJldG8u",o:"RW50cmFy",c:"Q2FuY2VsYXI="};
const dec=(s)=>new TextDecoder().decode(Uint8Array.from(atob(s),(c)=>c.charCodeAt(0)));
const fp=(t)=>{let x=2166136261;for(const c of t){x^=c.charCodeAt(0);x=Math.imul(x,16777619);}return (x>>>0).toString(36);};
const ID="wsp";
let frame=null;

function light(){const c=getComputedStyle(document.documentElement).getPropertyValue("--bg").trim();const m=c.match(/^#?([0-9a-f]{6})$/i);if(!m)return false;const n=parseInt(m[1],16);return (0.299*((n>>16)&255)+0.587*((n>>8)&255)+0.114*(n&255))>140;}
function vars(){
  const cs=getComputedStyle(document.documentElement);
  const v=(n)=>cs.getPropertyValue(n).trim();
  return ":root{--bg:"+v("--bg")+";--panel:"+v("--surface")+";--panel2:"+v("--surface-alt")+
    ";--line:"+v("--border")+";--ink:"+v("--text")+";--dim:"+v("--text-muted")+
    ";--acc:"+v("--primary")+";--acc2:"+v("--success")+"}"+
    "header{display:none}main{max-width:100%;padding:0 0 24px}"+
    "body{font-family:'Segoe UI',-apple-system,BlinkMacSystemFont,Roboto,Arial,sans-serif;background:transparent}"+
    ".sec>h2 em,#go{color:"+v("--primary-contrast")+"}"+".fact.key.ok,.note.ok{background:color-mix(in srgb,"+v("--success")+" 14%,transparent);border-color:color-mix(in srgb,"+v("--success")+" 38%,transparent);color:"+v("--success")+"}"+".fact.key.warn,.note{background:color-mix(in srgb,"+v("--warning")+" 14%,transparent);border-color:color-mix(in srgb,"+v("--warning")+" 38%,transparent);color:"+v("--warning")+"}"+".fact.key.bad,.note.bad{background:color-mix(in srgb,"+v("--danger")+" 14%,transparent);border-color:color-mix(in srgb,"+v("--danger")+" 38%,transparent);color:"+v("--danger")+"}"+(light()?".presets img{filter:opacity(.85)}":"");
}

function paint(){
  const doc=frame&&frame.contentDocument;
  if(!doc||!doc.head)return;
  let st=doc.getElementById("_v");
  if(!st){st=doc.createElement("style");st.id="_v";doc.head.appendChild(st);}
  st.textContent=vars();
}

function build(){
  const sec=document.createElement("section");
  sec.className="view view-list";
  sec.id="view-"+ID;
  sec.hidden=true;
  sec.innerHTML='<header class="view-header"><div><h2></h2><p class="hint"></p></div></header><div class="frame-wrap"><iframe></iframe></div>';
  sec.querySelector("h2").textContent=dec(S.n);
  sec.querySelector(".hint").textContent=dec(S.s);
  document.querySelector(".app-main").appendChild(sec);

  frame=sec.querySelector("iframe");
  frame.title=dec(S.n);
  frame.addEventListener("load",paint);
  frame.srcdoc=dec(P);

  const nav=document.createElement("button");
  nav.type="button";
  nav.className="nav-item";
  nav.dataset.view=ID;
  nav.innerHTML='<span class="nav-icon">\u{1F9E9}</span> ';
  nav.append(dec(S.n));
  document.querySelector(".side-nav").appendChild(nav);
  nav.click();
}

function ask(){
  const back=document.createElement("div");
  back.className="modal-backdrop";
  back.innerHTML='<div class="modal-card"><h3></h3><label class="field"><span></span><input type="password" inputmode="numeric" autocomplete="off"></label><p class="modal-err" hidden></p><div class="modal-actions"><button type="button" class="btn btn-ghost"></button><button type="button" class="btn btn-primary"></button></div></div>';
  back.querySelector("h3").textContent=dec(S.m);
  back.querySelector("label span").textContent=dec(S.p);
  const err=back.querySelector(".modal-err");
  err.textContent=dec(S.e);
  const btns=back.querySelectorAll(".modal-actions .btn");
  btns[0].textContent=dec(S.c);
  btns[1].textContent=dec(S.o);
  const inp=back.querySelector("input");
  const close=()=>{back.remove();document.removeEventListener("keydown",onKey);};
  const test=()=>{if(fp(inp.value.trim())===K){close();build();}else{err.hidden=false;inp.select();}};
  const onKey=(ev)=>{if(ev.key==="Escape")close();else if(ev.key==="Enter"&&document.activeElement===inp)test();};
  btns[0].addEventListener("click",close);
  btns[1].addEventListener("click",test);
  inp.addEventListener("input",()=>{err.hidden=true;});
  back.addEventListener("click",(ev)=>{if(ev.target===back)close();});
  document.addEventListener("keydown",onKey);
  document.body.appendChild(back);
  inp.focus();
}

function init(){
  const host=document.getElementById("view-settings");
  if(!host)return;
  const b=document.createElement("button");
  b.type="button";
  b.className="lock-dot";
  b.title=dec(S.m);
  b.textContent="\u{1F512}";
  b.addEventListener("click",()=>{
    const existing=document.querySelector('.nav-item[data-view="'+ID+'"]');
    if(existing)existing.click();else ask();
  });
  host.appendChild(b);
  document.addEventListener("calculaai:themechange",paint);
}

if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init();
})();
